const SB_URL='https://kekmppsuiiokdckdeolv.supabase.co';
const SB_KEY='process.env.SUPABASE_SERVICE_ROLE_KEY||''';
const input=$input.first().json;
const token=(input.token||'').replace(/^sk-/,'');
function authError(code,msg){return[{json:{_auth_error:true,error_code:code,message:msg}}]};
if(!token)return authError('AUTH_INVALID','missing token');
try{
const tResp=await this.helpers.httpRequest({method:'GET',url:SB_URL+'/rest/v1/tokens?select=id,status&key=eq.'+encodeURIComponent(token)+'&limit=1',headers:{apikey:SB_KEY,Authorization:'Bearer '+SB_KEY},json:true,timeout:5000});
if(!tResp.length||tResp[0].status!==1)return authError('AUTH_INVALID','invalid token');
return $input.all().map(function(item){var j=item.json;j._sb_key=SB_KEY;j._sb_url=SB_URL;return{json:j}});
}catch(e){return authError('AUTH_ERROR',String(e.message||e).slice(0,100))}

const cfg=$input.first().json;
const images=(cfg.images||[]).slice(0,10);
const cid=cfg.ozon_client_id||'';
const akey=cfg.ozon_api_key||'';
const productId=cfg.product_id||'';
const token=cfg.token||'';
const taskId=cfg.task_id||'video-'+Date.now();

if(!images.length) return [{json:{ok:false,error:'no images',task_id:taskId}}];
if(!productId) return [{json:{ok:false,error:'no product_id',task_id:taskId}}];

// 1. Generate video from 1688 product images via mxou
let videoUrl=null;
try{
  const resp=await this.helpers.httpRequest({
    method:'POST',
    url:'https://api.mxou.cn/v1/video/generations',
    headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},
    body:{model:'gpt-video-1',images:images,duration:Math.min(images.length*3,30),fps:1},
    json:true,timeout:180000
  });
  videoUrl=(resp.data||resp).url||(resp.data||resp).video_url||'';
}catch(e){}

if(!videoUrl){
  return [{json:{ok:false,error:'video gen failed',task_id:taskId}}];
}

// 2. Download video to re-upload COS
let videoBinary=null;
try{
  const dlResp=await this.helpers.httpRequest({method:'GET',url:videoUrl,encoding:'arraybuffer',timeout:120000});
  videoBinary=Buffer.from(dlResp);
}catch(e){}

// 3. Upload to COS (same bucket as images)
let cosUrl=null;
try{
  if(videoBinary){
    await this.helpers.httpRequest({
      method:'PUT',
      url:'https://yss-1256275613.cos.ap-guangzhou.myqcloud.com/ozon/videos/'+taskId+'.mp4',
      body:videoBinary,
      timeout:120000
    });
    cosUrl='https://yss-1256275613.cos.ap-guangzhou.myqcloud.com/ozon/videos/'+taskId+'.mp4';
  }
}catch(e){cosUrl=videoUrl}

// 4. Upload video to Ozon product
let ozonOk=false;
try{
  if(cid&&akey&&productId){
    await this.helpers.httpRequest({
      method:'POST',
      url:'https://api-seller.ozon.ru/v1/product/video/upload',
      headers:{'Client-Id':cid,'Api-Key':akey,'Content-Type':'application/json'},
      body:{product_id:parseInt(productId),video_url:cosUrl||videoUrl},
      json:true,timeout:30000
    });
    ozonOk=true;
  }
}catch(e){}

return [{json:{ok:true,task_id:taskId,cos_url:cosUrl,ozon_ok:ozonOk}}];
